  @ffi.Uint8()
  external int variance_octile;

  @ffi.Int8()
  external int sharpness;

  @ffi.Uint8()
  external int variance_boost_curve;

  @ffi.Uint8()
  external int luminance_qp_bias;

  @ffi.Bool()
  external bool lossless;

  @ffi.Bool()
  external bool avif;

  /// @brief Min chroma quant matrix flatness. Applicable when enable_qm is true.
  /// Min value is 0.
  /// Max value is 15.
  /// Default is 8.
  @ffi.Uint8()
  external int min_chroma_qm_level;

  /// @brief Max chroma quant matrix flatness. Applicable when enable_qm is true.
  /// Min value is 0.
  /// Max value is 15.
  /// Default is 15.
  @ffi.Uint8()
  external int max_chroma_qm_level;

  @ffi.Bool()
  external bool rtc;

  @ffi.Uint8()
  external int qp_scale_compress_strength;

  external SvtAv1SFramePositions sframe_posi;

  @ffi.Uint8()
  external int sframe_qp;

  @ffi.Int8()
  external int sframe_qp_offset;

  /// @brief Toggle default film grain blocksize behavior
  /// 0: use default blocksize behavior (32x32)
  /// 1: use adaptive blocksize based on resolution
  /// - 8x8 for <4k
  /// - 16x16 for 4k
  /// Default is 1
  @ffi.Bool()
  external bool adaptive_film_grain;

  @ffi.Uint8()
  external int max_tx_size;

  @ffi.Uint8()
  external int extended_crf_qindex_offset;

  /// @brief Strength of the internal RD metric to bias toward high-frequency error (helps with texture preservation and film grain retention)
  /// 0.00: disable AC bias
  /// 1.00: enable AC bias with a strength of 1.00
  /// Default is 0.00.
  @ffi.Double()
  external double ac_bias;

  /// @brief High Bit-Depth Mode Decision, used to control the bit-depth of the mode decision path.
  /// -1: preset determined (auto)
  /// 0: full 8-bit MD
  /// 1: full 10-bit MD
  /// 2: hybrid 8/10-bit MD
  /// Default is -1
  @ffi.Int()
  external int hbd_mds;

  /// @brief Enable MCTF for key frames.
  /// 0 = off
  /// 1 = on
  /// Default is 1.
  @ffi.Bool()
  external bool enable_tf_key;

  /// @brief Max Intra Bitrate Percentage
  ///
  /// Maximum bitrate for intra frames, expressed as a percentage of the
  /// target bitrate. 0 means no limit.
  ///
  /// Default is 300.
  @ffi.Uint32()
  external int max_intra_bitrate_pct;

  /// @brief Max Inter Bitrate Percentage
  ///
  /// Maximum bitrate for inter frames, expressed as a percentage of the
  /// target bitrate. 0 means no limit.
  ///
  /// Default is 0.
  @ffi.Uint32()
  external int max_inter_bitrate_pct;

  /// @brief Enable Intra Block Copy
  ///
  /// false: off
  /// true: on (default, preset-based)
  ///
  /// Default is true.
  @ffi.Bool()
  external bool enable_intrabc;

  /// @brief Ref-frame management — number of simultaneously STOREd refs
  /// the application may hold.
  ///
  /// 0 (default): feature disabled; legacy reference selection and the
  /// legacy buffer-pool size are preserved BIT-EXACTLY. No
  /// extra memory is allocated.
  /// 1..4       : enable the STORE / CLEAR / USE event API. The
  /// ref-buffer pool grows by this many entries (one full
  /// picture buffer each) to hold the locked anchors.
  /// The encoder still uses all 8 DPB slots dynamically;
  /// STORE locks one slot at a time, and CLEAR releases.
  ///
  /// Validation (svt_av1_verify_settings):
  /// - max_managed_refs <= 4
  /// - if > 0: pred_structure must be LOW_DELAY.
  ///
  /// ABI note: this field was added in place of one padding byte. The
  /// library expects EbSvtAv1EncConfiguration to be zero-initialized
  /// before configuration (which svt_av1_enc_init_handle guarantees);
  /// applications building this struct manually with uninitialized
  /// memory could silently inherit a non-zero value here from prior
  /// stack contents and unexpectedly enable the feature.
  @ffi.Uint8()
  external int max_managed_refs;

  @ffi.Array.multi([110])
  external ffi.Array<ffi.Uint8> padding;
}

